import math

alpha = math.sqrt(2)
results = {}

for m in range(1, 11):
    for n in range(1, 11):
        # Calculate m * ceil(n * alpha) - n * floor(m * alpha)
        term1 = m * math.ceil(n * alpha)
        term2 = n * math.floor(m * alpha)

        result = term1 - term2

        # Check if the result is a positive integer (since we expect integer results due to floor/ceil)
        if result > 0 and result == int(result):
            results[(m, n)] = int(result)

print("Found pretty pairs (m, n) for alpha=sqrt(2) and 1 <= m, n <= 10:")
for pair, val in sorted(results.items()):
    print(f"({pair[0]}, {pair[1]}): {val}")

